    pow2[0] = 1;
    for (int i = 1; i <= n; ++i) pow2[i] = addmod(pow2[i - 1], pow2[i - 1]);

    // DP for number of ways to place pairs with distance 1 or 2 on a line of length n
    // dp[i] = number of ways for first i positions
    vector<int> dp(n + 1);
    dp[0] = 1;
    for (int i = 0; i < n; ++i) {
        // leave position i+1 unmatched (will be opposite pair)
        dp[i + 1] = addmod(dp[i + 1], dp[i]);
        // pair (i+1, i+2)
        if (i + 2 <= n) dp[i + 2] = addmod(dp[i + 2], dp[i]);
        // pair (i+1, i+3)
        if (i + 3 <= n) dp[i + 3] = addmod(dp[i + 3], dp[i]);
    }

    // For each k = number of opposite pairs, compute contribution
    int ans = 0;
