        // number of ways to assign colors:
        // k opposite pairs and (n-k) non-opposite pairs -> total n pairs
        // colors are distinct, so n! permutations
        int colorPerm = fact[n];
        // beauty contribution: product of segment lengths.
        // For this combinatorial solution, it turns out to be 2^{k-1}.
        int beautyFactor = pow2[k - 1];

        int contrib = mulmod(chooseOpp, waysPairs);
        contrib = mulmod(contrib, colorPerm);
        contrib = mulmod(contrib, beautyFactor);
        ans = addmod(ans, contrib);
